INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('ugU2musG6f55vlHcOTw_Z', 'chatgpt-photo-editing-prompts', '25 ChatGPT Photo Editing Prompts You Can Copy and Paste', '25 ChatGPT photo editing prompts for headshots, backgrounds, lighting, and retro looks. Copy one, upload your photo, and edit in a single chat.', '<p>You do not need Photoshop to fix a photo anymore. You need the right sentence. Upload a photo to ChatGPT, paste one of the prompts below, and it will retouch, relight, or restyle the image in the same chat.</p><p>These 25 prompts cover the edits people actually ask for: headshots, background swaps, lighting fixes, and the retro looks that keep going viral. They all follow the same rule, one edit per prompt plus a line that protects your face. We keep a larger, always-updated list on our <a href="/chatgpt-photo-editing-prompt">ChatGPT photo editing prompt</a> page if you want more after these.</p><h2>Headshots and profile photos</h2><blockquote><p>"Create a professional LinkedIn-style headshot from my photo: neutral grey background, soft studio lighting, business casual attire. Keep my face natural and recognizable."</p></blockquote><blockquote><p>"Edit my photo into a clean profile picture: plain warm background, gentle light on my face, sharp eyes. Keep my face and hairstyle exactly the same."</p></blockquote><blockquote><p>"Make this photo look like it was taken by a professional photographer: better framing, softer light, natural skin. Do not change my face."</p></blockquote><blockquote><p>"Turn my casual photo into a formal portrait: dark suit, charcoal studio backdrop, single soft key light. Keep my face unchanged."</p></blockquote><h2>Background fixes</h2><blockquote><p>"Remove the clutter behind me and replace the background with a softly blurred modern interior. Keep me exactly as I am."</p></blockquote><blockquote><p>"Replace the background with a city street at dusk, lights softly out of focus. Match the lighting on me to the new scene. Keep my face and clothes the same."</p></blockquote><blockquote><p>"Put me in front of a plain white studio background, even lighting, e-commerce style. Keep everything about me unchanged."</p></blockquote><blockquote><p>"Change the background to a beach at golden hour, soft warm light on my face. Keep my face, pose, and outfit exactly the same."</p></blockquote><h2>Lighting and color</h2><blockquote><p>"Relight this photo with warm window light from the left, gentle shadows, natural skin tones. Change nothing else."</p></blockquote><blockquote><p>"Fix the exposure in this photo: brighten the shadows on my face, recover the sky, keep colors realistic. Keep my face unchanged."</p></blockquote><blockquote><p>"Grade this photo like a film still: teal shadows, warm highlights, soft contrast. Keep the framing and my face the same."</p></blockquote><blockquote><p>"Convert this photo to rich black and white: deep blacks, bright highlights, subtle grain. Keep every detail of my face."</p></blockquote><blockquote><p>"Give this photo a golden-hour glow: low warm sun from the side, soft lens flare, natural skin. Keep my face exactly as it is."</p></blockquote><h2>Retouching</h2><blockquote><p>"Retouch this photo lightly: even skin tone, reduce shine, remove stray hairs, keep real skin texture. Do not smooth my face into plastic."</p></blockquote><blockquote><p>"Remove the photobombers in the background of this photo. Keep me and everything else untouched."</p></blockquote><blockquote><p>"Clean up this photo: remove the water spots on the lens, fix the tilted horizon, sharpen gently. Keep my face unchanged."</p></blockquote><blockquote><p>"Restore this old photo: repair scratches, fix faded colors, sharpen faces carefully. Do not change how anyone looks."</p></blockquote><h2>Style and fun</h2><blockquote><p>"Restyle my photo as a 1990s film snapshot: grain, faded warm colors, direct flash look. Keep my face exactly the same."</p></blockquote><blockquote><p>"Turn my photo into a cinematic movie poster: dramatic sky behind me, moody lighting, space at the top for a title. Keep my face recognizable."</p></blockquote><blockquote><p>"Make my photo look like a Polaroid from the 80s: instant film border, slightly washed colors, soft focus. Keep my face the same."</p></blockquote><blockquote><p>"Turn me into a detailed collectible action figure in a branded box, studio product lighting. Keep my face clearly mine."</p></blockquote><blockquote><p>"Edit my photo into a cozy autumn portrait: falling leaves, warm scarf, soft overcast light. Keep my face and expression unchanged."</p></blockquote><h2>Outfits</h2><blockquote><p>"Change my outfit to a tailored black suit with a white shirt. Keep my face, pose, and the background exactly as they are."</p></blockquote><blockquote><p>"Dress me in traditional festive wear appropriate to the occasion, rich colors, subtle embroidery. Keep my face and pose unchanged."</p></blockquote><blockquote><p>"Swap my t-shirt for a smart casual blazer and keep everything else in the photo identical, including my face."</p></blockquote><h2>How to get the most out of these</h2><p>Correct one thing per message. If the first result is close, reply with a single fix: warmer, sharper, less blur. Stacked corrections confuse the model and quality drops fast.</p><p>When a chain of edits starts looking mushy, start a new chat and re-upload the original photo. Each generation is a copy of a copy, and after four or five rounds it shows.</p><p>And keep the face line in every message, not just the first one. ChatGPT regenerates the whole image each time, so the protection has to travel with each request. If faces keep drifting anyway, our guide on <a href="/blog/gemini-face-consistency">keeping your face consistent in AI edits</a> goes deeper into why that happens and how to stop it.</p>', 'McmtqjyuNXH9FeoCedda1', 'Dhananjay Kumar Nirala', 'published', '4 min read', '25 ChatGPT Photo Editing Prompts (Copy-Paste Ready)', '25 ChatGPT photo editing prompts for headshots, backgrounds, lighting, and retro looks. Copy one, upload your photo, and edit in a single chat.', '["how-to-edit-photos-with-ai-prompts","gemini-face-consistency","ai-photo-prompt-ideas"]', '[{"question":"How do I edit a photo with ChatGPT?","answer":"Upload the photo with the paperclip button, then describe the edit in the same message. ChatGPT returns a new edited image in the chat. Refine it with one correction at a time, like ''a bit warmer'' or ''less blur'', until it looks right."},{"question":"Which ChatGPT photo editing prompt should I start with?","answer":"The headshot prompt is the most forgiving: ''Create a professional headshot from my photo, neutral background, soft studio lighting. Keep my face natural and recognizable.'' It teaches you the pattern every other prompt on this list follows."},{"question":"Why does ChatGPT change my face when editing?","answer":"ChatGPT regenerates the entire image, so faces drift unless you anchor them. Add ''keep my exact facial features, do not alter my face'' to every edit message, and avoid heavy style words like ''ethereal'' or ''flawless'' which pull features out of shape."},{"question":"Are these prompts free to use?","answer":"Yes. All 25 prompts are free to copy, and ChatGPT''s free tier includes image editing with daily limits. If you edit a lot of photos, a paid plan raises the limits and uses the newer image models."}]', '2026-07-14T05:00:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('BoQjhKr36MEdb9j6rkV9g', 'how-to-edit-photos-with-ai-prompts', 'How to Edit Photos With AI Prompts: A Beginner''s Guide', 'Learn how to edit photos with AI prompts in Gemini or ChatGPT: the four-part prompt structure, real examples, and fixes for the most common failures.', '<p>Editing a photo with AI comes down to one skill: describing the change clearly. Upload your photo to Gemini or ChatGPT, type what you want changed and what must stay the same, and the model does the rest. No layers, no masks, no tutorials.</p><p>This guide teaches the structure that makes those descriptions work. Once you have it, you can improvise your own edits instead of hunting for prompts. If you would rather start from ready-made lines, our <a href="/photo-editing-prompt">photo editing prompt</a> library has dozens you can copy first and understand later.</p><h2>The four parts of every good editing prompt</h2><p>Every reliable editing prompt answers four questions. Miss one and the model starts guessing.</p><p><strong>1. The change.</strong> One clear edit. "Replace the background with a beach at sunset." Not three edits chained together; one. You can always run a second prompt for the second change.</p><p><strong>2. The keep line.</strong> What must not change. "Keep my face, hairstyle, and outfit exactly the same." This is the most skipped part and the most important one. AI editors regenerate the whole image, so anything you do not anchor is up for grabs.</p><p><strong>3. The look.</strong> The finish you want: "soft natural light", "warm film tones", "clean magazine style". One or two phrases, not a paragraph.</p><p><strong>4. The format.</strong> Only if it matters: portrait crop, square for Instagram, sharp focus on the eyes.</p><blockquote><p>"Replace the background with a quiet beach at sunset. Keep my face, hairstyle, and outfit exactly the same. Warm golden light, soft shadows. Portrait crop."</p></blockquote><p>That is the whole method. Everything else in this guide is refinement.</p><h2>Your first three edits</h2><p>Start with these, in this order. Each one teaches you something about how the model behaves.</p><blockquote><p>"Retouch this photo lightly: even out skin tone, reduce shine, keep real skin texture. Keep my face exactly the same."</p></blockquote><p>The light retouch shows you the model''s default taste. If it over-smooths, you know to push back with "keep pores and texture real" in future prompts.</p><blockquote><p>"Replace the background with a softly blurred city street in the evening. Match the lighting on me to the scene. Keep my face and clothes unchanged."</p></blockquote><p>The background swap teaches you about lighting. The phrase "match the lighting on me to the scene" is what separates a convincing composite from an obvious paste job.</p><blockquote><p>"Relight this photo with warm window light from the left, gentle shadows, natural skin tones. Change nothing else."</p></blockquote><p>The relight is the most useful everyday edit. Most mediocre photos are one lighting change away from good.</p><h2>Fixing the four most common failures</h2><p><strong>The face changed.</strong> Your keep line was missing, or your style words were stronger than it. Add "do not alter my facial features" and delete the most dramatic style word. Repeat until it holds.</p><p><strong>It looks plastic.</strong> The model over-retouched. Say "light retouch only, keep real skin texture, no smoothing". Never ask for "flawless" anything.</p><p><strong>It ignored part of the request.</strong> You asked for too much at once. Split the prompt into passes: background first, then light, then outfit. Each pass stays accurate because the model has one job.</p><p><strong>Each retry looks worse.</strong> You are editing an edit. Go back to the original photo and start again with the improved prompt. Generations degrade like photocopies.</p><h2>Gemini or ChatGPT?</h2><p>Same prompts, different personalities. Gemini is usually better at holding a face steady on the first attempt and is the tool behind most of the viral portrait trends. ChatGPT is better at conversation: you can nudge the result over several messages without re-explaining. Run your first few edits in both and see which fits how you work. The prompt structure carries over unchanged, and tool-specific lists live on our <a href="/gemini-photo-editing-prompt">Gemini</a> and <a href="/chatgpt-photo-editing-prompt">ChatGPT</a> pages.</p><h2>Where to go next</h2><p>Once editing feels comfortable, the next skill is generating images from scratch, which uses a slightly different structure. Our guide to <a href="/blog/anatomy-of-a-perfect-ai-image-prompt">the anatomy of a perfect AI image prompt</a> covers that. And when an edit fights you, the answer is almost always in the keep line, so start your debugging there.</p>', 'nfQi9dYFh9xm4zB5zW4T4', 'Dhananjay Kumar Nirala', 'published', '4 min read', 'How to Edit Photos With AI Prompts (Beginner''s Guide)', 'Learn how to edit photos with AI prompts in Gemini or ChatGPT: the four-part prompt structure, real examples, and fixes for the most common failures.', '["chatgpt-photo-editing-prompts","anatomy-of-a-perfect-ai-image-prompt","common-ai-prompt-mistakes"]', '[{"question":"What is the best AI tool for editing photos with prompts?","answer":"Gemini and ChatGPT are the two easiest. Gemini tends to hold faces steadier on the first attempt; ChatGPT is better at refining an edit over several messages. Both have free tiers, so try the same prompt in each and keep the one you like."},{"question":"How do I write my first photo editing prompt?","answer":"Use the four-part structure: the change, the keep line, the look, the format. For example: ''Replace the background with a plain studio grey (change), keep my face and outfit exactly the same (keep), soft natural light (look), portrait crop (format).''"},{"question":"Why do my AI photo edits look fake?","answer":"Usually over-retouching. Words like ''perfect'' and ''flawless'' push the model to smooth skin into plastic. Ask for a light retouch that keeps real skin texture, and prefer specific lighting descriptions over vague quality words."},{"question":"Can AI edit photos without changing my face?","answer":"Yes, if you tell it to. Include ''keep my face, features, and expression exactly the same'' in every prompt. Face drift happens when that line is missing or when heavy style words override it."}]', '2026-07-14T05:05:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('-fnuEbVuP_mzMfF2pq0yK', 'anatomy-of-a-perfect-ai-image-prompt', 'The Anatomy of a Perfect AI Image Prompt', 'A perfect AI image prompt has five parts: subject, style, light, framing, and medium. Learn the formula with worked examples for Gemini, ChatGPT, and Midjourney.', '<p>Strip any great AI image prompt down and you find the same skeleton: a subject, a style, a light source, a framing choice, and a medium. Five decisions. Make them explicitly and the model gives you what you imagined. Skip them and the model makes them for you, badly.</p><p>This post walks through each part with worked examples. If you want finished prompts to copy right now, our <a href="/ai-image-prompt">AI image prompt</a> library is the shortcut; this is the page that explains why those prompts work.</p><h2>Part one: the subject</h2><p>One noun, one or two concrete details. "A fisherman" is a category. "An elderly fisherman with weathered hands mending a net" is a picture. The detail does not need to be elaborate; it needs to be specific enough that two people reading it would imagine roughly the same person.</p><p>A useful test: if your subject could caption a thousand different photos, it is too vague.</p><h2>Part two: the style</h2><p>Photorealistic, watercolor, anime, 3D render, film still, charcoal sketch. This one word moves the output more than anything else in the prompt, which is why it should never be left implicit. The model has to pick a style either way; the only question is whether you chose it.</p><h2>Part three: the light</h2><p>Unlit prompts get the model''s default: flat, even, characterless. Name a light and the image gets a mood for free. "Golden hour", "single window light", "neon signs in the rain", "overcast and soft". Photographers spend careers on this decision; you get it in three words.</p><blockquote><p>"A street food vendor at his stall at night, photorealistic, lit only by the stall''s warm bulbs, steam rising, close-up, shot on 35mm film."</p></blockquote><p>Cover the light and the medium, and even a plain subject turns atmospheric.</p><h2>Part four: the framing</h2><p>Close-up, wide shot, low angle, overhead, centered symmetry. Framing is how you control what the image is about. The same subject framed close reads as a portrait; framed wide it reads as a scene. If you skip it, you get a medium shot, the least deliberate choice in photography.</p><h2>Part five: the medium</h2><p>"Shot on 85mm lens", "Kodak film grain", "oil on canvas", "editorial magazine photograph". The medium cue ties the other four parts together and quietly sets resolution, texture, and color behavior. One or two cues are enough. Piling on "ultra detailed 8k masterpiece best quality" is a habit from older models; current ones mostly ignore it, and it crowds out words that do work.</p><h2>The formula in action</h2><p>Here is the same idea at three levels of control.</p><blockquote><p>"A woman reading in a cafe."</p></blockquote><p>Model decides everything. Coin flip.</p><blockquote><p>"A young woman reading a worn paperback in a cafe window seat, photorealistic, soft morning light through the glass."</p></blockquote><p>Subject, style, and light covered. Recognizably your idea now.</p><blockquote><p>"A young woman reading a worn paperback in a cafe window seat, photorealistic, soft morning light through the glass, close-up from across the table, shallow depth of field, shot on 85mm lens."</p></blockquote><p>All five parts. This one comes back the way you pictured it, run after run.</p><h2>When you are editing, not generating</h2><p>Editing your own photo swaps one part of the formula: the subject is fixed, so the keep line takes its place. "Keep my face exactly the same" becomes the load-bearing sentence, and the other four parts describe the edit. That craft has its own guide: <a href="/blog/how-to-edit-photos-with-ai-prompts">how to edit photos with AI prompts</a>.</p><p>Either way, the discipline is identical. Five decisions, made on purpose. The models are good enough now that the gap between a random result and a great one is rarely the tool. It is whether the prompt made the decisions or dodged them.</p>', 'nfQi9dYFh9xm4zB5zW4T4', 'Dhananjay Kumar Nirala', 'published', '4 min read', 'The Anatomy of a Perfect AI Image Prompt (5-Part Formula)', 'A perfect AI image prompt has five parts: subject, style, light, framing, and medium. Learn the formula with worked examples for Gemini, ChatGPT, and Midjourney.', '["how-to-edit-photos-with-ai-prompts","how-to-write-midjourney-prompts","prompt-patterns-that-work"]', '[{"question":"What are the five parts of a good AI image prompt?","answer":"Subject, style, light, framing, and medium. Name what you want to see, the visual style, the light source, how the shot is framed, and what medium it should imitate, like 35mm film or oil paint. One or two sentences covering those five will outperform a paragraph of adjectives."},{"question":"Does the same prompt formula work in Gemini, ChatGPT, and Midjourney?","answer":"Yes. All three read natural language, so the five-part structure transfers directly. Midjourney users often add parameter flags for aspect ratio, but the descriptive words stay the same."},{"question":"Do words like ''8k'' and ''masterpiece'' improve AI images?","answer":"Not anymore. Modern models mostly ignore quality incantations, and stacking them dilutes the words that matter. One concrete medium cue, like ''shot on 35mm film'' or ''editorial photograph'', does more than ten quality adjectives."},{"question":"Why does my prompt give a different image every time?","answer":"Image models sample from probabilities, so variation is built in. Run the prompt three or four times and pick the best. If results vary too wildly, the prompt is under-specified; adding a framing or lighting instruction tightens the spread."}]', '2026-07-14T05:10:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('kEt5YGfGxcUA92NnirZAK', 'gemini-face-consistency', 'How to Keep Your Face Consistent in Gemini AI Edits', 'Gemini changed your face again? Here is why AI edits drift, the keep line that stops it, and a checklist for photos that survive heavy styling.', '<p>The most common complaint about Gemini photo edits is not quality. It is "that is not me." The saree looks perfect, the lighting is cinematic, and the face belongs to a stranger who vaguely resembles you.</p><p>This is fixable. Face drift has three causes, and each has a specific counter. By the end of this post you will know all three, and your edits will survive even heavy styling.</p><h2>Why the face changes at all</h2><p>Gemini does not edit your photo the way Photoshop does, patching only the pixels you point at. It studies your image, then generates a new one that follows your instructions. Everything is redrawn, your face included. Preservation is not the default; it is a request you have to make.</p><p>Once you know that, the fix is obvious: make the request, every single time.</p><h2>Cause one: no keep line</h2><p>The keep line is one sentence that anchors what must not change:</p><blockquote><p>"Keep my face, facial features, and expression exactly the same. Do not alter my identity."</p></blockquote><p>Add it to the end of any editing prompt. And here is the part people miss: add it to the follow-ups too. When you reply "make the light warmer", Gemini regenerates the image again, and a keep line from three messages ago protects nothing. Every generation needs its own.</p><h2>Cause two: style words that overpower it</h2><p>Style words and preservation pull in opposite directions. "Ethereal dreamy fantasy portrait, dramatic cinematic glow" tells the model to reinvent the image; "keep my face" tells it not to. When the style stack gets heavy enough, style wins.</p><p>The fix is a trade you control. Cut the most dramatic style word and check whether your face holds. Repeat until it does. In practice "warm light" does most of what "ethereal cinematic golden dream glow" was doing, without costing you your face.</p><h2>Cause three: a weak source photo</h2><p>The model can only preserve what it can see. A checklist for the photo you upload:</p><ul><li>Face large in the frame, not a distant full-body shot</li><li>Sharp focus, no motion blur</li><li>Even light on the face, no harsh half-shadow</li><li>No sunglasses, no heavy beauty filters</li><li>Front-facing or close to it</li></ul><p>Group photos deserve a special note: the smallest faces drift first. If one person keeps breaking in a family edit, start from a photo where they are closer to the camera.</p><h2>A prompt that survives heavy styling</h2><p>Putting all three fixes together:</p><blockquote><p>"Edit my photo: drape me in a flowing red chiffon saree on a golden-hour terrace, warm natural light. Keep my face, facial features, and expression exactly the same. Do not alter my identity."</p></blockquote><p>Strong scene, moderate style words, explicit keep line. Run it two or three times and pick the best, because generation is probabilistic and the spread between attempts is real.</p><h2>When it still drifts</h2><p>Two escalations. First, simplify: run the edit in two passes, outfit first with a keep line, then background with a keep line. Each pass is easier to hold than one big transformation. Second, if you are producing a set of images that must match, the Pro model holds identity across images better than the standard one.</p><p>Face consistency is the difference between an edit you post and an edit you delete, and it comes down to habits, not luck. For ready-made prompts that already have the keep line built in, browse our <a href="/gemini-ai-photo-prompt">Gemini AI photo prompt</a> collection, or see what everyone is copying this month on the <a href="/trending-gemini-prompt">trending Gemini prompts</a> page.</p>', 'nfQi9dYFh9xm4zB5zW4T4', 'Dhananjay Kumar Nirala', 'published', '3 min read', 'How to Keep Your Face Consistent in Gemini AI Edits', 'Gemini changed your face again? Here is why AI edits drift, the keep line that stops it, and a checklist for photos that survive heavy styling.', '["trending-gemini-prompts","chatgpt-photo-editing-prompts","turn-your-photo-into-an-ai-portrait"]', '[{"question":"Why does Gemini change my face when I edit a photo?","answer":"Gemini regenerates the whole image rather than patching pixels, so your face is redrawn every time. Without an explicit instruction to preserve it, and with strong style words pulling against it, the redrawn face drifts away from yours."},{"question":"What is the keep line for Gemini prompts?","answer":"A sentence that anchors what must not change, such as ''keep my face, features, and expression exactly the same''. Put it in every prompt, including follow-up corrections, because each new generation needs the instruction again."},{"question":"What kind of photo works best for face-preserving edits?","answer":"A sharp, well-lit, front-facing photo where your face is large in the frame. No sunglasses, no motion blur, no heavy filters. The model can only preserve detail it can actually see in the source."},{"question":"Do style words really break face consistency?","answer":"Yes. Heavy stylization competes directly with preservation. Words like ''ethereal'', ''dramatic'', and ''fantasy'' push the model to reinvent the image, face included. If your face drifts, remove the strongest style word and try again."}]', '2026-07-14T05:15:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('_ITbLjMfPxJGY_k578d9Z', 'how-to-use-nano-banana-ai-free', 'How to Use Nano Banana AI for Free (Step-by-Step)', 'Nano Banana is free inside Gemini. Here is exactly where to find it, how many edits the free tier allows, and the prompts to run first.', '<p>Nano Banana is free. It is not a separate app you have to hunt down: it is the image model inside Google Gemini, and the free tier covers everyday editing with a daily limit. If you have a Google account, you are four steps away from your first edit.</p><h2>Step 1: open Gemini</h2><p>Go to gemini.google.com in any browser, or install the Gemini app on Android or iPhone. Sign in with a regular Google account. No card, no trial, no separate signup. If someone is selling you "Nano Banana access", close the tab; the real thing is free.</p><h2>Step 2: upload one good photo</h2><p>Tap the plus or image icon and pick a photo. This choice matters more than the prompt. Use a sharp, well-lit, front-facing shot where your face is big in the frame. Skip sunglasses, group shots, and anything blurry. The model can only preserve what it can see.</p><h2>Step 3: paste a prompt</h2><p>Type what you want changed and what must stay the same. Start with a proven one:</p><blockquote><p>"Turn me into a detailed collectible figurine standing on a desk, still in a branded box beside me, studio lighting. Keep my face exactly the same."</p></blockquote><blockquote><p>"Edit my photo into a 90s film portrait: grainy texture, warm faded colors, plain studio backdrop. Keep my face unchanged."</p></blockquote><blockquote><p>"Create a clean professional headshot from my photo: neutral background, soft studio light, formal attire. Keep my face natural and recognizable."</p></blockquote><p>The sentence at the end of each prompt, the keep line, is not decoration. It is what stops the model redrawing your face into a stranger''s. Keep it in every prompt you ever run. Hundreds more ready-made lines live on our <a href="/nano-banana-prompt">nano banana prompt</a> page.</p><h2>Step 4: correct, do not rewrite</h2><p>First result close but not right? Reply with one correction: "less grain", "warmer light", "keep my glasses". One change per message. If quality degrades after several rounds, start a fresh chat and re-upload the original photo.</p><h2>What the free tier actually gets you</h2><p>Google adjusts the exact numbers, but the shape is stable: a daily cap on image generations that resets each day, standard model access, and occasional slowdowns at peak hours. For a few edits a day it is genuinely enough. You hit the ceiling when you batch-produce, need text inside images, or want a matching set of portraits; that is <a href="/nano-banana-pro">Nano Banana Pro</a> territory, and part of what paid plans buy.</p><h2>Free-tier tactics</h2><ul><li>Decide the edit before you spend a generation. Three thoughtful prompts beat ten vague ones, and the cap stops mattering.</li><li>Rerun your best prompt two or three times and pick the winner; variation between runs is normal.</li><li>Save prompts that worked. A personal list of five reliable lines is worth more than any trend roundup.</li><li>Check the watermark policy where you post; AI-edited images carry invisible SynthID marking either way.</li></ul><p>That is the whole setup. Free, no app, four steps. The difference between people who get magazine-grade results and everyone else is not access; it is prompt habits, and those are learnable in an afternoon. If you are curious how the current model compares with the newer releases, we break that down in <a href="/blog/nano-banana-vs-pro-vs-2">Nano Banana vs Pro vs 2</a>.</p>', 'ASYDB3thDh46Z3r6kTiOH', 'Dhananjay Kumar Nirala', 'published', '3 min read', 'How to Use Nano Banana AI for Free (Step-by-Step Guide)', 'Nano Banana is free inside Gemini. Here is exactly where to find it, how many edits the free tier allows, and the prompts to run first.', '["nano-banana-vs-pro-vs-2","nano-banana-prompts","gemini-face-consistency"]', '[{"question":"Is Nano Banana AI really free?","answer":"Yes. Nano Banana is the image model inside Google Gemini, and the free tier includes image generation and editing with a daily cap. Casual use, a handful of edits a day, fits comfortably inside it. Paid plans raise the limits and unlock the Pro model."},{"question":"Where do I find Nano Banana? Is there an app?","answer":"There is no separate Nano Banana app. Open the Gemini app or gemini.google.com, sign in with a Google account, and upload a photo with your prompt. The image model that responds is what everyone calls Nano Banana."},{"question":"Why does Nano Banana refuse some of my prompts?","answer":"It moderates images of real people conservatively, especially children, and blocks edits that could mislead or sexualize. Rephrase toward photographic qualities like lighting and background. Some refusals are permanent by design."},{"question":"How do I keep my face from changing in Nano Banana edits?","answer":"End every prompt with a keep line: ''keep my face exactly the same''. Use a sharp, front-facing photo, and go easy on dramatic style words, which are the usual cause of face drift."}]', '2026-07-14T05:20:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('GyajiLHZqN-CkLUl1L3_u', 'nano-banana-vs-pro-vs-2', 'Nano Banana vs Nano Banana Pro vs Nano Banana 2: What Actually Changed', 'Three versions of Google''s viral image model, one honest comparison: speed, text rendering, face consistency, and which one to use for which job.', '<p>Google has shipped three generations of its viral image model: the original Nano Banana that started the figurine craze, the heavier Nano Banana Pro, and the newest Nano Banana 2. The names are confusing and the differences are real, so here is the honest version of what changed and when each one is worth using.</p><h2>The thirty-second answer</h2><p>The original is fast and good enough for everyday edits. Pro trades speed for capability: text inside images, print-grade resolution, and faces that stay consistent across a whole set. Nano Banana 2 is the refinement generation: it follows complicated instructions more faithfully and drifts faces less, so you spend fewer attempts getting what you asked for.</p><h2>Where each one wins</h2><p><strong>Original Nano Banana.</strong> The trend machine. Figurines, retro portraits, saree edits, quick background swaps. Its weaknesses are known: garbled small text, face drift under heavy styling, and chaos when a prompt asks for too much at once. If you write disciplined prompts, one change plus a keep line, it still delivers most of what the newer models do.</p><p><strong>Nano Banana Pro.</strong> The one you switch to when output quality has consequences. Birthday posters where the name has to be spelled right. A set of three matching portraits for a profile. Anything you plan to print or crop hard. It is slower per image and free-tier access is limited, which is exactly the trade you would expect.</p><p><strong>Nano Banana 2.</strong> The one that makes prompts feel obeyed. Ask for a rainy street, a red umbrella, neon reflections, and your unchanged face, and you are far more likely to get all four in one attempt. Old prompts run on it without any rewriting and generally come out better.</p><h2>Try the difference yourself</h2><p>Run this on whichever model your Gemini gives you, then on Pro if you have access:</p><blockquote><p>"Design a small birthday poster from my photo with the text HAPPY BIRTHDAY in bold letters, warm balloon background. Keep my face exactly the same."</p></blockquote><p>The text is the tell. The original mangles lettering more often than not, Nano Banana 2 gets short text right maybe most of the time, and Pro treats it almost like a solved problem.</p><h2>What has not changed</h2><p>Three constants across every version. Prompts are identical, so everything on our <a href="/nano-banana-prompt">nano banana prompt</a> page works on all three. The keep line is still mandatory; newer models respect "keep my face exactly the same" more reliably, but none of them assume it. And moderation is consistent: requests involving real people get refused conservatively no matter which model you run.</p><h2>Practical picks</h2><ul><li>Daily fun edits and trends: whatever model loads by default. Do not overthink it.</li><li>Text in the image: <a href="/nano-banana-pro">Pro</a>, no contest.</li><li>A matching set of portraits: Pro, for cross-image consistency.</li><li>Complex layered scenes: <a href="/nano-banana-2">Nano Banana 2</a> if you have it, else split the edit into passes.</li><li>On a strict free tier: the standard model, spent carefully. Our <a href="/blog/how-to-use-nano-banana-ai-free">free-tier guide</a> covers how to stretch it.</li></ul><p>Version chasing is mostly noise. The people getting the best results out of these models are not the ones on the newest release; they are the ones with five saved prompts that work. Pick the model that fits the job, keep your keep line, and let the trends come to you.</p>', 'ASYDB3thDh46Z3r6kTiOH', 'Dhananjay Kumar Nirala', 'published', '3 min read', 'Nano Banana vs Pro vs Nano Banana 2: What Actually Changed', 'Three versions of Google''s viral image model, one honest comparison: speed, text rendering, face consistency, and which one to use for which job.', '["how-to-use-nano-banana-ai-free","nano-banana-prompts","gemini-face-consistency"]', '[{"question":"What is the difference between Nano Banana and Nano Banana Pro?","answer":"Pro is the slower, more capable variant: higher resolution output, far better text inside images, and steadier faces across a set of pictures. The standard model is faster and fine for one-off edits. Same prompts work on both."},{"question":"What is new in Nano Banana 2?","answer":"The newest generation follows multi-part instructions more faithfully and needs less coaxing to keep faces consistent. Complicated scenes fall apart less often. Small text in images improved but is still not fully reliable."},{"question":"Which Nano Banana version should I use?","answer":"Quick one-off edits: the standard model. Posters, invitations, anything with text, or matching multi-image sets: Pro. If your Gemini gives you the newest model by default, just use it; your existing prompts carry over unchanged."},{"question":"Do I need to rewrite my prompts for the newer models?","answer":"No. The prompt language is identical across versions. Keep the keep line (''keep my face exactly the same'') in every prompt regardless of model; newer versions respect it more reliably, but all of them need to be told."}]', '2026-07-14T05:25:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('2Firxtr6WQlQtfBmVn58h', 'trending-gemini-prompts', '25 Trending Gemini AI Photo Prompts This Month (July 2026)', 'The Gemini photo prompts everyone is copying right now: monsoon portraits, retro film looks, figurines, and festive edits. Updated for July 2026.', '<p>Prompt trends move fast: one week it is figurines in boxes, the next it is rain-soaked monsoon portraits. This is the July 2026 snapshot of what people are actually pasting into Gemini right now, cleaned up and given the one thing viral screenshots always omit: the keep line that protects your face.</p><p>Copy any line as-is, or change one detail to make it yours. For the continuously updated version of this list, bookmark our <a href="/trending-gemini-prompt">trending Gemini prompt</a> page.</p><h2>Monsoon mood (the moment)</h2><blockquote><p>"Edit my photo: I am standing on a rainy street under a black umbrella, warm shop lights reflecting on the wet road, light drizzle visible. Keep my face exactly the same."</p></blockquote><blockquote><p>"Turn my photo into a monsoon portrait: raindrops on a window in front of me, soft grey light, cozy tones. Keep my face unchanged."</p></blockquote><blockquote><p>"Place me on a tea stall bench during heavy rain, steam from a cup in my hand, cinematic warm-cold contrast. Keep my face the same."</p></blockquote><h2>The evergreen viral three</h2><blockquote><p>"Turn me into a detailed collectible figurine standing on a desk, still in a branded box beside me, studio lighting. Keep my face exactly the same."</p></blockquote><blockquote><p>"Drape me in a flowing red chiffon saree, wind in the fabric, golden-hour terrace backdrop, cinematic warm light. Keep my face exactly the same."</p></blockquote><blockquote><p>"Edit my photo into a 1990s film portrait: grain, faded warm colors, vintage outfit, plain studio backdrop. Keep my face unchanged."</p></blockquote><h2>Portraits people keep sharing</h2><blockquote><p>"A dramatic black and white close-up portrait from my photo: deep shadows, single light from the side, film grain. Keep my face exactly as it is."</p></blockquote><blockquote><p>"Edit my photo into a golden-hour rooftop portrait: warm sun behind me, soft flare, city softly blurred below. Keep my face and hairstyle the same."</p></blockquote><blockquote><p>"Create a royal portrait from my photo: rich traditional outfit, palace corridor background, warm evening light. Keep my face and expression unchanged."</p></blockquote><blockquote><p>"A clean studio portrait on a deep blue background, soft key light, magazine cover style. Keep my face natural and unchanged."</p></blockquote><h2>Cinematic scenes</h2><blockquote><p>"Place me in a night market scene: neon signs, food stalls glowing, shallow depth of field. Keep my face and outfit exactly the same."</p></blockquote><blockquote><p>"Edit my photo into a railway platform scene at dawn, fog, one warm lamp, cinematic tones. Keep my face unchanged."</p></blockquote><blockquote><p>"Turn my photo into a movie poster: dramatic sky, wind in my clothes, title space left blank at the top. Keep my face recognizable."</p></blockquote><blockquote><p>"Place me walking through a field of tall grass at sunset, backlit, lens flare, film look. Keep my face the same."</p></blockquote><h2>Retro and aesthetic</h2><blockquote><p>"Make my photo look like an 80s Polaroid: instant film border, washed colors, direct flash. Keep my face exactly the same."</p></blockquote><blockquote><p>"Edit my photo into a vinyl album cover: bold color grade, centered composition, subtle text space at the bottom. Keep my face unchanged."</p></blockquote><blockquote><p>"A soft pastel aesthetic portrait: cream background, gentle window light, minimal styling. Keep my face exactly as it is."</p></blockquote><blockquote><p>"Turn my photo into 70s retro style: warm orange tones, patterned shirt, slight film blur at the edges. Keep my face the same."</p></blockquote><h2>Professional</h2><blockquote><p>"Create a professional headshot from my photo: neutral grey background, soft studio lighting, business attire. Keep my face natural and recognizable."</p></blockquote><blockquote><p>"Edit my photo for a resume: clean background, approachable expression kept as-is, balanced natural light. Do not change my face."</p></blockquote><blockquote><p>"A confident speaker-on-stage edit: soft spotlight on me, dark blurred audience behind, professional tone. Keep my face unchanged."</p></blockquote><h2>Festive and seasonal</h2><blockquote><p>"Edit my photo into a festive portrait: warm string lights and marigold decor behind me, rich colors, gentle bokeh. Keep my face and outfit the same."</p></blockquote><blockquote><p>"A birthday portrait from my photo: pastel balloon arch behind me, confetti falling, soft festive light. Keep my face exactly the same."</p></blockquote><blockquote><p>"Turn my photo into a winter portrait: light snowfall, warm coat, cold blue background with one warm light source. Keep my face unchanged."</p></blockquote><blockquote><p>"Edit my photo into a beach vacation shot: golden sand, evening waves behind me, relaxed summer colors. Keep my face and pose the same."</p></blockquote><h2>Make any of these hold up</h2><p>Three habits separate clean results from deleted ones. Use a sharp, front-facing source photo. Never delete the keep line, even in follow-up corrections. And rerun the prompt a few times before judging it; the spread between attempts is where the viral-quality results hide. If your face keeps drifting anyway, our <a href="/blog/gemini-face-consistency">face consistency guide</a> fixes that properly.</p>', 'McmtqjyuNXH9FeoCedda1', 'Dhananjay Kumar Nirala', 'published', '4 min read', '25 Trending Gemini AI Photo Prompts (July 2026)', 'The Gemini photo prompts everyone is copying right now: monsoon portraits, retro film looks, figurines, and festive edits. Updated for July 2026.', '["gemini-couple-photo-prompt-ideas","gemini-face-consistency","ai-photo-prompt-ideas"]', '[{"question":"What Gemini photo prompt is trending right now?","answer":"Monsoon-themed portraits are having a moment in July: rain-soaked streets, umbrellas, warm light through the drizzle. The chiffon saree edit and desk figurine remain the most copied prompts overall. Every version on this page includes the face-preserving keep line."},{"question":"How do I use these trending prompts?","answer":"Open Gemini, upload one clear front-facing photo, and paste a prompt as-is. Rerun it two or three times and keep the best result. To personalize it, change one detail, the color or the setting, and leave the rest of the sentence intact."},{"question":"Why do my results look worse than the viral posts?","answer":"Viral posts are the best of many attempts on good source photos. Use a sharp, well-lit photo, keep the keep line, and generate a few variations before judging. The gap is usually the source photo, not the prompt."},{"question":"Are these prompts free?","answer":"Yes, all of them, and Gemini''s free tier covers a limited number of edits per day. No signup is needed to copy anything on this page."}]', '2026-07-14T05:30:00.000Z', NULL);
INSERT INTO posts (id, slug, title, excerpt, content, category_id, author_name, status, read_time, meta_title, meta_description, related_slugs, faq_items, published_at, cover_image) VALUES ('qwZ9kEQ50A_hOKTSeTJWm', 'gemini-couple-photo-prompt-ideas', '20 Gemini Couple Photo Prompt Ideas That Keep Both Faces Real', '20 Gemini couple photo prompts for anniversaries, pre-wedding looks, retro edits, and casual portraits, each with the keep line for both faces.', '<p>Couple edits are twice as hard as solo ones for a simple reason: two faces means two chances for the AI to drift. The prompts below are built around that reality. Every one of them names both people in the keep line, which is the single change that fixes most bad couple edits.</p><p>Upload one clear photo where both faces are visible and roughly the same size, then copy away. More couple-specific lines live on our <a href="/gemini-couple-photo-prompt">Gemini couple photo prompt</a> page.</p><h2>Romantic classics</h2><blockquote><p>"Edit this photo of us into a golden-hour portrait: warm sun behind us, soft flare, field of tall grass. Keep both of our faces exactly the same."</p></blockquote><blockquote><p>"Create an elegant anniversary portrait: formal outfits, candlelit restaurant softly blurred behind us, gentle romantic light. Keep both of our faces unchanged."</p></blockquote><blockquote><p>"Turn this photo into a rainy-evening scene: one umbrella over us both, wet street reflecting warm lights. Keep both faces exactly as they are."</p></blockquote><blockquote><p>"Edit us into a rooftop dinner scene at dusk: string lights above, city lights softly blurred behind. Keep both of our faces the same."</p></blockquote><blockquote><p>"A cozy winter portrait of us: light snowfall, matching wool coats, warm light from a cafe window beside us. Keep both faces unchanged."</p></blockquote><h2>Pre-wedding looks</h2><blockquote><p>"Create a pre-wedding style portrait from this photo: coordinated traditional outfits, palace courtyard at sunset, cinematic warm tones. Keep both of our faces exactly the same."</p></blockquote><blockquote><p>"Edit us into a beach pre-wedding shot: flowing outfits, waves behind us, golden evening light. Keep both faces unchanged."</p></blockquote><blockquote><p>"A garden pre-wedding portrait: pastel outfits, flower arch behind us, soft daylight. Keep both of our faces exactly as they are."</p></blockquote><blockquote><p>"Turn this photo into a classic black and white pre-wedding portrait: formal wear, dramatic soft light, timeless look. Keep both faces the same."</p></blockquote><h2>Retro and fun</h2><blockquote><p>"Edit this couple photo into a 90s film look: grain, faded warm colors, vintage outfits, plain studio backdrop. Keep both of our faces exactly the same."</p></blockquote><blockquote><p>"Turn us into a retro Bollywood movie poster: dramatic poses kept as-is, painted style, title space at the top. Keep both faces recognizable."</p></blockquote><blockquote><p>"Make this photo look like an 80s Polaroid of us: instant film border, washed colors, direct flash. Keep both faces unchanged."</p></blockquote><blockquote><p>"Turn us both into detailed collectible figurines in one branded box labeled as a set, studio product lighting. Keep both of our faces clearly ours."</p></blockquote><h2>Everyday and casual</h2><blockquote><p>"Edit this photo into a cozy coffee-shop scene: we are at a window table, warm light, soft background chatter feel. Keep both of our faces exactly the same."</p></blockquote><blockquote><p>"A casual evening-walk portrait: tree-lined street, warm streetlights, relaxed tones. Keep both faces and outfits unchanged."</p></blockquote><blockquote><p>"Edit us into a road-trip photo: leaning on a vintage car, open highway behind, late-afternoon light. Keep both of our faces the same."</p></blockquote><blockquote><p>"A festival portrait of us: warm string lights and marigold decor behind, rich colors, gentle bokeh. Keep both faces exactly as they are."</p></blockquote><h2>Milestones</h2><blockquote><p>"Create a formal portrait for our wedding invitation: coordinated outfits, soft studio light, plain elegant backdrop, space at the bottom for text. Keep both of our faces exactly the same."</p></blockquote><blockquote><p>"An engagement announcement portrait: ring hand gently visible, soft garden background, warm light. Keep both faces unchanged and natural."</p></blockquote><blockquote><p>"Edit this photo into a milestone anniversary portrait: elegant evening wear, warm golden backdrop, classic composition. Keep both of our faces the same."</p></blockquote><h2>When one face keeps breaking</h2><p>It is almost always the smaller or side-turned face. Pick a source photo where you are both facing the camera at similar distance, and say "keep both of our faces" rather than a generic keep line. If it still drifts, run the edit at a closer crop, then ask Gemini to extend the scene afterward. The full troubleshooting method is in our <a href="/blog/gemini-face-consistency">face consistency guide</a>.</p>', 'McmtqjyuNXH9FeoCedda1', 'Dhananjay Kumar Nirala', 'published', '4 min read', '20 Gemini Couple Photo Prompt Ideas (Copy-Paste)', '20 Gemini couple photo prompts for anniversaries, pre-wedding looks, retro edits, and casual portraits, each with the keep line for both faces.', '["trending-gemini-prompts","gemini-face-consistency","chatgpt-photo-editing-prompts"]', '[{"question":"How do I edit a couple photo in Gemini without changing our faces?","answer":"Write the keep line to cover both people explicitly: ''keep both of our faces exactly the same''. A generic keep line often protects only the more prominent face. Use a sharp photo where both faces are clearly visible and similar in size."},{"question":"What is the best couple photo prompt for an anniversary?","answer":"Try: ''Create an elegant anniversary portrait from this photo: formal outfits, warm candlelit restaurant softly blurred behind us, gentle romantic light. Keep both of our faces exactly the same.'' Swap the setting for a beach, terrace, or garden as you like."},{"question":"Can Gemini make a pre-wedding style shoot from one photo?","answer":"Yes. Upload one clear photo of you both and run the pre-wedding prompts on this page, changing outfits and locations between runs. Expect to generate each look a few times and keep the best; two faces means twice the chances of drift."},{"question":"Do these prompts work if we are in separate photos?","answer":"Combining two separate photos into one scene is less reliable than editing one photo of you together. If you must combine, upload both images in one message and say who is who, but a single clear photo of both of you gives far better results."}]', '2026-07-14T05:35:00.000Z', NULL);
